def sector_weeks(days):
    """Weekly (Mon-start, by filing date) buy/sell per sector for each scope, plus the week's top company."""
    wk = lambda iso: (dt.date.fromisoformat(iso) - dt.timedelta(days=dt.date.fromisoformat(iso).weekday())).isoformat()
    weeks = sorted({wk(d["date"]) for d in days})
    ix = {w: i for i, w in enumerate(weeks)}
    S = {}
    def cell(sec, who):
        return S.setdefault(sec, {}).setdefault(who, [[0, 0, {}] for _ in weeks])
    for d in days:
        i = ix[wk(d["date"])]
        for s in d.get("sectors") or []:
            for who, b, sl in (("eff", s.get("buy_eff_usd", s.get("buy_od_usd")) or 0, s.get("sell_eff_usd") or 0),
                               ("inst", s.get("buy_inst_usd") or 0, s.get("sell_inst_usd") or 0),
                               ("od", s.get("buy_od_usd") or 0, s.get("sell_od_usd") or 0),
                               ("all", s.get("buy_usd") or 0, s.get("sell_usd") or 0)):
                c = cell(s["sector"], who)[i]; c[0] += b; c[1] += sl
        for co in d.get("companies") or []:
            k = co.get("ticker") or co.get("name") or ""
            for who, net in (("eff", (co.get("eff_buy_usd") or 0) - (co.get("eff_sell_usd") or 0)),
                             ("inst", (co.get("inst_buy_usd") or 0) - (co.get("inst_sell_usd") or 0)),
                             ("od", (co.get("eff_buy_usd") or 0) - (co.get("eff_sell_usd") or 0)),
                             ("all", (co.get("buy_usd") or 0) - (co.get("sell_usd") or 0))):
                if net:
                    tc = cell(co.get("sector") or "", who)[i][2]; tc[k] = tc.get(k, 0) + net
    out = {}
    for sec, by in S.items():
        out[sec] = {}
        for who, arr in by.items():
            rows = []
            for b, sl, tc in arr:
                net = b - sl
                top = max(tc.items(), key=lambda kv: kv[1] if net >= 0 else -kv[1]) if tc else None
                rows.append([round(b), round(sl)] + ([top[0], round(top[1])] if top and top[1] and (top[1] > 0) == (net >= 0) else []))
            out[sec][who] = rows
    return {"weeks": weeks, "S": out}


