def main():
    days_dir, index_html, out = sys.argv[1:4]
    shutil.rmtree(out, ignore_errors=True); os.makedirs(out + "/data")
    dates, days = [], []
    for p in sorted(glob.glob(os.path.join(days_dir, "*.json"))):
        d = json.load(open(p, encoding="utf-8"))
        if isinstance(d, dict) and "data" in d and "sectors" not in d: d = d["data"]
        if not (isinstance(d, dict) and d.get("date") and d.get("sectors")): continue
        json.dump(d, open(f"{out}/data/{d['date']}.json", "w", encoding="utf-8"), separators=(",", ":"), ensure_ascii=False)
        dates.append(d["date"]); days.append(d)
    dates = sorted(set(dates))
    json.dump({"dates": dates, "updated": dt.datetime.now(dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"), "sw": sector_weeks(days)}, open(f"{out}/data/manifest.json", "w"), separators=(",", ":"), ensure_ascii=False)
    lang_pages(open(index_html, encoding="utf-8").read(), out)
    pages = company_pages(days, out)
    feeds(days, out)
    sm = [f"<url><loc>{SITE}/{p}</loc><lastmod>{dates[-1]}</lastmod><changefreq>daily</changefreq></url>" for p in ("", "themes/ai/", "themes/energy/", "calendar/", "overview/", "insider/", "en/", "zh/", "tw/")]
    sm += [f"<url><loc>{SITE}/s/{s}.html</loc><lastmod>{lm}</lastmod></url><url><loc>{SITE}/tw/s/{s}.html</loc><lastmod>{lm}</lastmod></url>" for s, lm in sorted(pages)]
    open(f"{out}/sitemap.xml", "w").write('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + "".join(sm) + "</urlset>")
    open(f"{out}/robots.txt", "w").write(f"User-agent: *\nAllow: /\nSitemap: {SITE}/sitemap.xml\n")
    has_home = stack_page(out)
    # Articles (/articles/): built by scripts/build_articles.py from articles/src (loaded by path: python3 -I drops the script dir from sys.path)
    import importlib.util
    _spec = importlib.util.spec_from_file_location("build_articles", os.path.join(os.path.dirname(os.path.abspath(__file__)), "build_articles.py"))
    _ba = importlib.util.module_from_spec(_spec); _spec.loader.exec_module(_ba)
    art_paths = _ba.build(out)
    # Calendar (/calendar/): macro releases, Fed meetings, market holidays from data/macro.json (scripts/fetch_macro.py)
    _spec = importlib.util.spec_from_file_location("build_calendar", os.path.join(os.path.dirname(os.path.abspath(__file__)), "build_calendar.py"))
    _bc = importlib.util.module_from_spec(_spec); _spec.loader.exec_module(_bc)
    if (cal := _bc.build(out, _ba.page)): art_paths.insert(0, cal)
    os.makedirs(f"{out}/overview", exist_ok=True)
    shutil.copyfile(os.path.join(os.path.dirname(index_html), "overview.html"), f"{out}/overview/index.html")
    # Homepage (/): built by scripts/build_home.py, the entry point to every section
    _spec = importlib.util.spec_from_file_location("build_home", os.path.join(os.path.dirname(os.path.abspath(__file__)), "build_home.py"))
    _bh = importlib.util.module_from_spec(_spec); _spec.loader.exec_module(_bh)
    _bh.build(out, days, pages, _ba, _bc)
    sm += [f"<url><loc>{SITE}/{p}</loc><lastmod>{dates[-1]}</lastmod></url>" for p in art_paths]
    open(f"{out}/sitemap.xml", "w").write('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + "".join(sm) + "</urlset>")
    open(f"{out}/favicon.svg", "w").write(ICON_SVG)
    for n, b64 in ICONS.items():
        open(f"{out}/{n}.png", "wb").write(base64.b64decode(b64))
    open(f"{out}/subscribed.html", "w", encoding="utf-8").write(SUB_PAGE)
    os.makedirs(f"{out}/fonts", exist_ok=True)
    for fn, b64 in FONTS.items():
        open(f"{out}/fonts/{fn}", "wb").write(base64.b64decode(b64))
    for fn, b64 in (("og.png", OG_PNG_B64), ("og-tw.png", OG_TW_B64), ("og-en.png", OG_EN_B64)):
        if b64: open(f"{out}/{fn}", "wb").write(base64.b64decode(b64))
    open(f"{out}/_headers", "w").write("/fonts/*\n  Cache-Control: public, max-age=31536000, immutable\n/data/*\n  Cache-Control: public, max-age=300\n/index.html\n  Cache-Control: public, max-age=300\n"
                                       "/feed*.xml\n  Content-Type: application/rss+xml; charset=utf-8\n  Cache-Control: public, max-age=900\n"
                                       "/stack/data.json\n  Cache-Control: public, max-age=300\n/energy/data.json\n  Cache-Control: public, max-age=300\n/themes/*\n  Cache-Control: public, max-age=300\n/insider/\n  Cache-Control: public, max-age=300\n"
                                       "/s/*\n  Cache-Control: public, max-age=3600\n/tw/s/*\n  Cache-Control: public, max-age=3600\n/articles/*\n  Cache-Control: public, max-age=300\n/market/*\n  Cache-Control: public, max-age=300\n/calendar/*\n  Cache-Control: public, max-age=300\n")
    open(f"{out}/_redirects", "w").write("/stack /themes/ai/ 301\n/stack/ /themes/ai/ 301\n/ai /themes/ai/ 301\n/ai/ /themes/ai/ 301\n"
                                         "/energy /themes/energy/ 301\n/energy/ /themes/energy/ 301\n/themes /themes/ai/ 302\n/themes/ /themes/ai/ 302\n"
                                         "/articles /market/ 301\n/articles/ /market/ 301\n")
    print(f"built {len(dates)} days: {dates[0]} .. {dates[-1]}; {len(pages)} company pages; feeds + sitemap")


if __name__ == "__main__":
    main()
